/// The fitted field.
///
/// Built by the unchecked constructor because every argument is a literal in this file;
/// `sdtm_reference.rs` puts the same six through `Thermosphere::from_coefficients`,
/// `with_flux_excess` and `with_storm_gain` and asserts they accept them, which is where the
/// refusals bind.
pub const FIELD: Thermosphere<HARMONICS> = Thermosphere::from_fitted(
    COEFFICIENTS,
    3.341439818644104e-05,
    0.49658530381854077,
    StormResponse::Cooling(NitricOxideCooling {
        heating: 62950.24178295275,
        nitric_oxide: 118648.59040774021,
        saturation: 24.77339239626375,
    }),
    FluxExcess::Saturated {
        scale: 0.2631458364167668,
    },
    StormGain::FluxPower {
        exponent: -1.2993430094625682,
    },
);

/// Number of 3-hourly `ap` intervals the storm state is to be run over: the shortest whole
/// number of days whose truncation moves the driver by less than a hundredth of an `ap` at
/// every interval of the corpus span (worst 0.0063).
pub const HISTORY: usize = 120;

